/* @autogenerated */
package net.civeira.phylax.features.oauth.client.infrastructure.driven;

import java.math.BigInteger;
import java.security.AlgorithmParameters;
import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.PublicKey;
import java.security.interfaces.ECPublicKey;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.ECGenParameterSpec;
import java.security.spec.ECParameterSpec;
import java.security.spec.ECPoint;
import java.security.spec.ECPublicKeySpec;
import java.security.spec.RSAPublicKeySpec;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import com.auth0.jwt.JWT;
import com.auth0.jwt.algorithms.Algorithm;
import com.auth0.jwt.exceptions.JWTVerificationException;
import com.auth0.jwt.interfaces.DecodedJWT;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.features.oauth.client.domain.ClientDetails;
import net.civeira.phylax.features.oauth.client.domain.gateway.ClientJwtSignatureGateway;

/**
 * Verifies JWTs signed by a client with the keys of its JWKS: the inline one ({@code jwks_json}) or
 * the remote one ({@code jwks_uri}, fetched by {@link RemoteJwksFetcher}), task 3.3.
 *
 * <p>
 * Asymmetric algorithms only, {@code RS256} and {@code ES256} (P-256), and the one the client
 * registered when it registered one. The key is chosen by {@code kid}; without it, every key of the
 * right type is tried. Time claims get 60 seconds of leeway; the business checks are done by the
 * caller.
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class JwksSignatureAdapter implements ClientJwtSignatureGateway {

  private static final Set<String> ALGORITHMS = Set.of("RS256", "ES256");
  private static final long LEEWAY_SECONDS = 60;

  private final RemoteJwksFetcher fetcher;
  private final ObjectMapper mapper;

  @Override
  public Optional<Map<String, Object>> verify(ClientDetails client, String jwt) {
    DecodedJWT unverified;
    try {
      unverified = JWT.decode(jwt);
    } catch (JWTVerificationException ex) {
      return Optional.empty();
    }
    String alg = unverified.getAlgorithm();
    String registered = client.getRequestObjectSigningAlg();
    if (!ALGORITHMS.contains(alg) || registered != null && !registered.equals(alg)) {
      log.warn("Client {} signed with a forbidden algorithm {}", client.getClientId(), alg);
      return Optional.empty();
    }
    for (PublicKey key : keys(client, alg, unverified.getKeyId())) {
      try {
        Algorithm algorithm = "RS256".equals(alg) ? Algorithm.RSA256((RSAPublicKey) key, null)
            : Algorithm.ECDSA256((ECPublicKey) key, null);
        DecodedJWT verified =
            JWT.require(algorithm).acceptLeeway(LEEWAY_SECONDS).build().verify(jwt);
        Map<String, Object> claims = new HashMap<>();
        verified.getClaims().forEach((name, claim) -> claims.put(name, claim.as(Object.class)));
        return Optional.of(claims);
      } catch (JWTVerificationException ex) {
        log.debug("JWT of client {} not verified with a key: {}", client.getClientId(),
            ex.getMessage());
      }
    }
    return Optional.empty();
  }

  private List<PublicKey> keys(ClientDetails client, String alg, String kid) {
    Optional<String> jwks =
        Optional.ofNullable(client.getJwksJson()).filter(j -> !j.isBlank()).or(() -> Optional
            .ofNullable(client.getJwksUri()).filter(u -> !u.isBlank()).flatMap(fetcher::fetch));
    if (jwks.isEmpty()) {
      return List.of();
    }
    String kty = "RS256".equals(alg) ? "RSA" : "EC";
    List<PublicKey> result = new ArrayList<>();
    try {
      for (JsonNode jwk : mapper.readTree(jwks.get()).path("keys")) {
        boolean matches = kty.equals(jwk.path("kty").asText())
            && (kid == null || kid.equals(jwk.path("kid").asText(null)))
            && (!jwk.has("use") || "sig".equals(jwk.path("use").asText()))
            && (!jwk.has("alg") || alg.equals(jwk.path("alg").asText()));
        if (matches) {
          toKey(jwk).ifPresent(result::add);
        }
      }
    } catch (java.io.IOException ex) {
      log.warn("Unreadable JWKS of client {}", client.getClientId());
    }
    return result;
  }

  private static Optional<PublicKey> toKey(JsonNode jwk) {
    try {
      if ("RSA".equals(jwk.path("kty").asText())) {
        return Optional.of(KeyFactory.getInstance("RSA")
            .generatePublic(new RSAPublicKeySpec(number(jwk, "n"), number(jwk, "e"))));
      }
      if (!"P-256".equals(jwk.path("crv").asText())) {
        return Optional.empty();
      }
      AlgorithmParameters parameters = AlgorithmParameters.getInstance("EC");
      parameters.init(new ECGenParameterSpec("secp256r1"));
      ECParameterSpec spec = parameters.getParameterSpec(ECParameterSpec.class);
      return Optional.of(KeyFactory.getInstance("EC").generatePublic(
          new ECPublicKeySpec(new ECPoint(number(jwk, "x"), number(jwk, "y")), spec)));
    } catch (GeneralSecurityException | IllegalArgumentException ex) {
      return Optional.empty();
    }
  }

  private static BigInteger number(JsonNode jwk, String field) {
    return new BigInteger(1, Base64.getUrlDecoder().decode(jwk.path(field).asText()));
  }
}
